import{j as e}from"./index-bgjLzysl.js";import{S as t}from"./ServicePageLayout-mzBKTyB-.js";import{G as a}from"./gift-Bpd-qB7e.js";import"./button-ZYFniPzf.js";import"./PageBanner-BV1yeA7I.js";import"./Breadcrumbs-DQ9nGFto.js";import"./chevron-right-CteMLyDy.js";function u(){return e.jsx(t,{title:"Airtime Rewards",subtitle:"Instant Airtime & Data Rewards via API",description:"Reward customers instantly with airtime and data top-ups through MobiWave’s API — for campaigns, referrals, surveys, loyalty and field incentives. Disburse to any Kenyan number on Safaricom, Airtel and Telkom in real time, with reconciliation and 24/7 local support on one account that also bundles SMS, USSD and M-Pesa.",icon:a,stats:[{value:"3",label:"Kenya Networks"},{value:"Instant",label:"Disbursement"},{value:"API",label:"Triggered"},{value:"24/7",label:"Nairobi Support"}],features:["Instant airtime top-up to any Kenyan number","Data bundle disbursement","REST API + webhook confirmation","All three networks: Safaricom, Airtel, Telkom","Campaign and referral triggers","Loyalty and points redemption","Real-time reconciliation","Spend controls and limits","Bulk disbursement via CSV or API","Bundled with SMS, USSD and M-Pesa"],benefits:["Reward customers the moment they act — no waiting","Universal reach across all Kenyan networks","Drives referrals, surveys and repeat engagement","Transparent reconciliation and spend controls","Easy API integration with webhook confirmations","24/7 local Nairobi support via phone and WhatsApp"],useCases:[{title:"Referral rewards",description:"Auto-credit airtime to customers who refer friends."},{title:"Survey incentives",description:"Thank respondents with airtime the moment they complete a survey."},{title:"Loyalty redemptions",description:"Let members redeem points for airtime and data."},{title:"Field & agent incentives",description:"Top up agents and field staff for verified activities."},{title:"Promotions & contests",description:"Disburse prizes instantly to campaign winners."},{title:"Onboarding rewards",description:"Welcome new users with a data bundle to get started."},{title:"Grants & relief",description:"Deliver airtime support to beneficiaries at scale."},{title:"App engagement",description:"Reward daily logins, milestones or content creation."}],howItWorks:[{step:"1",title:"Fund your rewards wallet",description:"Top up your MobiWave rewards wallet (via M-Pesa or invoice). This balance backs every airtime and data disbursement you trigger."},{step:"2",title:"Integrate the API",description:"Call the airtime API with the recipient number, network and amount, or upload a CSV for bulk disbursement. Webhooks confirm each successful top-up."},{step:"3",title:"Set triggers",description:"Wire rewards to events — a completed referral, survey, purchase or milestone — so incentives fire automatically."},{step:"4",title:"Disburse instantly",description:"Airtime or data hits the recipient’s line in real time across Safaricom, Airtel and Telkom, with a confirmation callback."},{step:"5",title:"Reconcile",description:"Track every disbursement, cost and failure in the dashboard, with exportable reports for finance."},{step:"6",title:"Bundle with messaging",description:"Notify winners and redeemers by SMS or WhatsApp from the same MobiWave account and billing line."}],comparisonTable:{headers:["MobiWave","Africa's Talking","Celcom Africa","Twilio"],note:"MobiWave disburses across all three Kenyan networks from one wallet and bundles rewards with SMS, USSD and M-Pesa. Airtime is billed at cost plus a small service fee.",rows:[{name:"Airtime across 3 networks",cells:[{text:"Safaricom, Airtel, Telkom",highlight:!0},{text:"Yes"},{text:"Yes"},{text:"Limited"}]},{name:"Data bundle disbursement",cells:[{text:"Yes",highlight:!0},{text:"Yes"},{text:"Yes"},{text:"Limited"}]},{name:"API + webhook confirm",cells:[{text:"Yes",highlight:!0},{text:"Yes"},{text:"Yes"},{text:"Yes"}]},{name:"Single rewards wallet",cells:[{text:"Yes",highlight:!0},{text:"Yes"},{text:"Yes"},{text:"N/A"}]},{name:"Bundle with SMS & M-Pesa",cells:[{text:"One account",highlight:!0},{text:"Add-ons"},{text:"Add-ons"},{text:"Separate"}]},{name:"Local 24/7 support",cells:[{text:"Phone + WhatsApp",highlight:!0},{text:"Developer-only"},{text:"Business hours"},{text:"No local team"}]}]},pricing:[{title:"Pay-as-you-go",price:"At cost + fee",unit:"",features:["Airtime + data across 3 networks","API + webhook confirm","Realtime reconciliation","Standard support"]},{title:"Campaigns",price:"At cost + fee",unit:"",features:["Everything in Pay-as-you-go","Bulk CSV disbursement","Triggers & limits","24/7 support"]},{title:"Enterprise",price:"Custom",unit:"",features:["High-volume rewards","Custom SLAs","Dedicated wallet controls","Dedicated account manager"]}],faqs:[{question:"How much do airtime rewards cost?",answer:"You pre-fund a rewards wallet and pay the face value of the airtime or data plus a small service fee — there are no setup fees. Because top-ups go out at cost, your only variable is the reward value you choose to give. Contact us for the current service-fee rate."},{question:"Which networks are supported?",answer:"MobiWave disburses airtime and data across Safaricom, Airtel and Telkom, so you can reward any Kenyan subscriber from a single wallet and API."},{question:"How fast is disbursement?",answer:"Disbursement is near-instant — airtime or data typically lands on the recipient’s line in real time, with a webhook confirmation you can use to update your own systems."},{question:"Can I trigger rewards from my app?",answer:"Yes. Call the airtime API with the recipient number, network and amount, or upload a CSV for bulk campaigns. Webhooks confirm each successful top-up for reconciliation."},{question:"Can I run a referral program with airtime?",answer:"Yes. Wire the API to your referral event so a completed referral auto-credits airtime to the referrer, with spend controls and fraud limits."},{question:"Is there a minimum or maximum?",answer:"Minimum and maximum top-up values follow each network’s denominations. Enterprise customers can set per-transaction and per-recipient limits for control."},{question:"How do you handle failed disbursements?",answer:"Failed top-ups are reported via webhook and not deducted from your wallet, so you only pay for successful rewards. You can retry or flag the number in your dashboard."},{question:"Can rewards be combined with SMS notifications?",answer:"Yes. Notify winners and redeemers by SMS or WhatsApp from the same MobiWave account, so the reward and the message share one billing line."},{question:"Do you support data bundles too?",answer:"Yes. Beyond voice airtime, you can disburse data bundles to keep customers connected as part of the same rewards flow."},{question:"How is MobiWave different from Africa’s Talking?",answer:"Both disburse airtime across networks. MobiWave bundles rewards with bulk SMS, USSD and M-Pesa on one account, adds data-bundle disbursement and 24/7 local phone/WhatsApp support, and provides built-in reconciliation and spend controls for campaigns."}]})}export{u as AirtimeRewards};
